def minStickers(stickers: list[str], target: str) -> int:
    from collections import Counter
    m = len(target)
    memo = {(1 << m) - 1: 0}
    def dfs(mask):
        if mask in memo: return memo[mask]
        first_char = ''
        for i in range(m):
            if not (mask & (1 << i)):
                first_char = target[i]
                break
        ans = float('inf')
        for st in stickers:
            if first_char not in st:
                continue
            next_mask = mask
            cnt = Counter(st)
            for i in range(m):
                if not (next_mask & (1 << i)) and cnt[target[i]] > 0:
                    cnt[target[i]] -= 1
                    next_mask |= (1 << i)
            if next_mask != mask:
                ans = min(ans, 1 + dfs(next_mask))
        memo[mask] = ans
        return ans
    res = dfs(0)
    return res if res != float('inf') else -1

